// Configurar fechas
const endDate = new Date();
const startDate = new Date();
startDate.setDate(startDate.getDate() - 7); // Últimos 7 días

const formatDate = (date) => {
  return date.toISOString().split('T')[0];
};

// Preparar items para cada proyecto
const items = [];
for (const project of $input.all()) {
  items.push({
    json: {
      projectId: project.json.id,
      projectName: project.json.name,
      startDate: formatDate(startDate),
      endDate: formatDate(endDate),
      defaultBranch: project.json.default_branch || 'main'
    }
  });
}

return items;

const commits = $input.all();
const enrichedCommits = [];

for (const commitItem of commits) {
  const commit = commitItem.json;

  // Analizar calidad del mensaje
  const messageQuality = commit.message && commit.message.length >= 15;

  // Detectar reversiones
  const isRevert = commit.message && commit.message.toLowerCase().includes('revert');

  // Detectar referencias a issues
  const hasIssueRef = commit.message && /#[0-9]+/.test(commit.message);

  // Detectar referencias a MR
  const hasMrRef = commit.message && /![0-9]+/.test(commit.message);

  // Determinar si es fuera de horario laboral (9-18)
  const commitDate = new Date(commit.committed_date);
  const hour = commitDate.getHours();
  const day = commitDate.getDay(); // 0 = Domingo, 6 = Sábado

  const isWorkHour = hour >= 9 && hour < 18 && day >= 1 && day <= 5;
  const isWeekend = day === 0 || day === 6;

  enrichedCommits.push({
    json: {
      ...commit,
      projectId: commitItem.json.projectId,
      projectName: commitItem.json.projectName,
      message_quality: messageQuality,
      is_revert: isRevert,
      has_issue_ref: hasIssueRef,
      has_mr_ref: hasMrRef,
      is_work_hour: isWorkHour,
      is_weekend: isWeekend,
      hour: hour,
      day_of_week: day,
      message_length: commit.message ? commit.message.length : 0
    }
  });
}

return enrichedCommits;

const items = $input.all();
const metrics = [];

// Agrupar por proyecto y usuario
const groupedData = {};

for (const item of items) {
  const commit = item.json;
  const key = `${commit.projectId}_${commit.author_id || commit.author_email}`;

  if (!groupedData[key]) {
    groupedData[key] = {
      projectId: commit.projectId,
      projectName: commit.projectName,
      authorId: commit.author_id,
      authorName: commit.author_name,
      authorEmail: commit.author_email,
      commits: [],
      totalAdditions: 0,
      totalDeletions: 0,
      totalFiles: 0,
      commitsOutsideHours: 0,
      commitsWeekend: 0,
      qualityMessages: 0,
      issueRefs: 0,
      mrRefs: 0,
      reverts: 0
    };
  }

  const group = groupedData[key];
  group.commits.push(commit);

  if (commit.stats) {
    group.totalAdditions += commit.stats.additions || 0;
    group.totalDeletions += commit.stats.deletions || 0;
    group.totalFiles += commit.stats.total || 0;
  }

  if (!commit.is_work_hour) group.commitsOutsideHours++;
  if (commit.is_weekend) group.commitsWeekend++;
  if (commit.message_quality) group.qualityMessages++;
  if (commit.has_issue_ref) group.issueRefs++;
  if (commit.has_mr_ref) group.mrRefs++;
  if (commit.is_revert) group.reverts++;
}

// Calcular métricas
for (const key in groupedData) {
  const g = groupedData[key];
  const totalCommits = g.commits.length;

  if (totalCommits > 0) {
    metrics.push({
      json: {
        project_id: g.projectId,
        project_name: g.projectName,
        user_id: g.authorId,
        user_name: g.authorName,
        user_email: g.authorEmail,
        metric_date: new Date().toISOString().split('T')[0],
        commits_count: totalCommits,
        total_additions: g.totalAdditions,
        total_deletions: g.totalDeletions,
        total_files_changed: g.totalFiles,
        avg_commit_size: Number(((g.totalAdditions + g.totalDeletions) / totalCommits).toFixed(2)),
        commits_outside_work_hours: g.commitsOutsideHours,
        commits_weekend: g.commitsWeekend,
        commits_with_quality_message: g.qualityMessages,
        commits_with_issue_ref: g.issueRefs,
        commits_with_mr_ref: g.mrRefs,
        revert_commits: g.reverts,
        quality_percentage: Number(((g.qualityMessages / totalCommits) * 100).toFixed(2)),
        issue_ref_percentage: Number(((g.issueRefs / totalCommits) * 100).toFixed(2)),
        revert_rate: Number(((g.reverts / totalCommits) * 100).toFixed(2)),
        outside_hours_percentage: Number(((g.commitsOutsideHours / totalCommits) * 100).toFixed(2))
      }
    });
  }
}

return metrics;

const items = $input.all();
const alerts = [];

for (const item of items) {
  if (item.json.revert_rate > 5) {
    alerts.push({
      json: {
        project_id: item.json.project_id,
        user_id: item.json.user_id,
        metric_name: 'revert_rate',
        metric_value: item.json.revert_rate,
        threshold_value: 5,
        severity: 'critical',
        message: `Alta tasa de reversiones: ${item.json.revert_rate.toFixed(2)}% en el proyecto ${item.json.project_name} - Usuario: ${item.json.user_name}`
      }
    });
  }
}

return alerts;

const items = $input.all();
const alerts = [];

for (const item of items) {
  if (item.json.quality_percentage < 80) {
    alerts.push({
      json: {
        project_id: item.json.project_id,
        user_id: item.json.user_id,
        metric_name: 'message_quality',
        metric_value: item.json.quality_percentage,
        threshold_value: 80,
        severity: 'warning',
        message: `Baja calidad de mensajes: ${item.json.quality_percentage.toFixed(2)}% en el proyecto ${item.json.project_name} - Usuario: ${item.json.user_name}`
      }
    });
  }
}

return alerts;
